"const { GoogleGenAI } = require('@google/genai');
require('dotenv').config();

const ai = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY });

async function run() {
  const chat = ai.chats.create({
    model: 'gemini-1.5-flash',
    config: {
      tools: [{
        functionDeclarations: [{
          name: 'getWeather',
          description: 'Get weather',
          parameters: { type: 'OBJECT', properties: { location: { type: 'STRING' } } }
        }]
      }]
    }
  });

  try {
    let response = await chat.sendMessage("What is the weather in Paris?");
    console.log("Model response:", response.functionCalls);

    if (response.functionCalls) {
      const call = response.functionCalls[0];
      const toolResponseData = [{
        functionResponse: {
          name: call.name,
          response: { weather: "Sunny, 25C" }
        }
      }];

      console.log("Sending tool response...");
      // Try sending it
      let finalResponse = await chat.sendMessage(toolResponseData);
      console.log("Final response:", finalResponse.text);
    }
  } catch (e) {
    console.error("Error:", e.message);
  }
}

run();"

